CREATE VIEW [dbo].[ApparecchiStorico2] AS  SELECT 'NSL' AS Categoria ,'New Slot' AS Tipo, storico.codicelocale AS IdLocale,2 AS TipoOggetto,'NSL' AS TipoOggettoDesc,dedicati.iddedicato AS CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, 1 AS TM ,NULL AS idmove, storico.idstorico, 0 AS IdPadre, storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 0 AS Ordinamento, 0 AS OrdinamentoCategoria  FROM storico,dedicati WHERE dedicati.iddedicato=storico.codiceoggetto AND dedicati.partipologiamonopoli=1 AND storico.tipo=2 UNION SELECT 'C7A' AS Categoria, 'Gioco' AS Tipo, storico.codicelocale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,storico.CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, 2 AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre , storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 0 AS Ordinamento, 1 AS OrdinamentoCategoria   FROM storico,dedicati WHERE dedicati.iddedicato=storico.codiceoggetto AND dedicati.partipologiamonopoli=2  AND storico.tipo=2 UNION SELECT 'C7C' AS Categoria, 'Gioco' AS Tipo, storico.codicelocale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,storico.CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, 4 AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre , storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 0 AS Ordinamento, 2 AS OrdinamentoCategoria   FROM storico,dedicati WHERE dedicati.iddedicato=storico.codiceoggetto AND dedicati.partipologiamonopoli=4  AND storico.tipo=2 UNION SELECT 'MEC' AS Categoria, 'Gioco' AS Tipo, storico.codicelocale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,storico.CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, NULL AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre , storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 0 AS Ordinamento, 3 AS OrdinamentoCategoria   FROM storico,dedicati WHERE dedicati.iddedicato=storico.codiceoggetto AND (dedicati.partipologiamonopoli>4 OR dedicati.partipologiamonopoli IS NULL)  AND storico.tipo=2 UNION SELECT 'NSL' AS Categoria, 'Mobile' AS Tipo, storico.codicelocale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,storico.CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, 1 AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre,storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 2 AS Ordinamento, 0 AS OrdinamentoCategoria   FROM storico,mobili WHERE mobili.idmobile=storico.codiceoggetto  AND ParTipologiaMonopoli=1 AND storico.tipo=0 UNION SELECT 'C7A' AS Categoria, 'Mobile' AS Tipo, storico.codicelocale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,storico.CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, 2 AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre,storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 2 AS Ordinamento, 0 AS OrdinamentoCategoria   FROM storico,mobili WHERE mobili.idmobile=storico.codiceoggetto  AND ParTipologiaMonopoli=2 AND storico.tipo=0 UNION SELECT 'C7C' AS Categoria, 'Mobile' AS Tipo, storico.codicelocale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,storico.CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, 4 AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre,storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 2 AS Ordinamento, 0 AS OrdinamentoCategoria   FROM storico,mobili WHERE mobili.idmobile=storico.codiceoggetto  AND ParTipologiaMonopoli=4 AND storico.tipo=0 UNION SELECT 'MEC' AS Categoria, 'Mobile' AS Tipo, storico.codicelocale AS IdLocale,0 AS TipoOggetto,'MOB' AS TipoOggettoDesc,storico.CodiceOggetto,mobili.prop AS Proprieta,mobili.agente AS Associato, mobili.matricola,mobili.modello as Modello, mobili.identificativo,mobili.nullaosta, NULL AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre,storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 2 AS Ordinamento, 0 AS OrdinamentoCategoria   FROM storico,mobili WHERE mobili.idmobile=storico.codiceoggetto  AND (ParTipologiaMonopoli>4 OR ParTipologiaMonopoli IS NULL) AND storico.tipo=0 UNION SELECT 'SCH' AS Categoria, 'Scheda' AS Tipo, storico.codicelocale,1 AS TipoOggetto,'SCH' AS TipoOggettoDesc, storico.CodiceOggetto,schede.prop AS Proprieta,schede.agente AS Associato, schede.matricola,schede.nome as Modello, '' AS identificativo,'' AS nullaosta, NULL AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre,storico.ndatainizio as DataDa, storico.ndatafine as DataA, datacreazione, fornitore, costruttore, idmagazzino, 3 AS Ordinamento, 0 AS OrdinamentoCategoria   FROM storico ,schede WHERE schede.idscheda=storico.codiceoggetto AND  storico.tipo=1 UNION SELECT 'DIS' AS Categoria, 'Distributore' AS Tipo, storico.codicelocale AS IdLocale,15 AS TipoOggetto,'DIS' AS TipoOggettoDesc, storico.CodiceOggetto,distribut.prop AS Proprieta,distribut.agente AS Associato, distribut.matricola,distribut.nome as Modello, '' AS identificativo,'' AS nullaosta, NULL AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre,storico.ndatainizio as DataDa, storico.ndatafine as DataA , datacreazione, fornitore, costruttore, idmagazzino, 4 AS Ordinamento, 0 AS OrdinamentoCategoria  FROM storico,distribut WHERE distribut.iddistributore=storico.codiceoggetto AND  storico.tipo=15 UNION SELECT 'ACC' AS Categoria, 'Accessorio' AS Tipo, storico.codicelocale AS IdLocale,3 AS TipoOggetto,'ACC' AS TipoOggettoDesc, storico.CodiceOggetto,Accessori.prop AS Proprieta,'' AS Associato, Accessori.matricola,Accessori.nome as Modello, '' AS identificativo,'' AS nullaosta, NULL AS TM, NULL AS idmove, storico.idstorico, 0 AS IdPadre,storico.ndatainizio as DataDa, storico.ndatafine as DataA , datacostruzione, fornitore, costruttore, idmagazzino, 5 AS Ordinamento, 0 AS OrdinamentoCategoria  FROM storico,Accessori WHERE Accessori.idAccessorio = storico.codiceoggetto AND  storico.tipo=3
GO
